import type { ToolRunner } from "@bithumb-official/bithumb-core";
import type { CliValues } from "../parser.js";
import { toNumber, parsePositiveInt } from "../parser.js";
import { outputLine, errorLine, printJson, printTable, printKv } from "../formatter.js";

export async function handleSystemCommand(
  run: ToolRunner,
  action: string | undefined,
  v: CliValues,
  json: boolean,
): Promise<void> {
  switch (action) {
    case "diagnose":
      return cmdDiagnose(run, json);
    case "audit":
      return cmdAudit(run, {
        limit: parsePositiveInt("limit", toNumber(v.limit, "limit")),
        tool: v.tool,
        since: v.since,
        level: v.level,
        json,
      });
    default:
      errorLine(`Unknown system command: ${action ?? "(none)"}. Run 'bithumb system --help' for usage.`);
      process.exitCode = 1;
  }
}

async function cmdDiagnose(run: ToolRunner, json: boolean): Promise<void> {
  const result = await run("system_diagnose", {});
  const data = result.data ?? result;
  if (json) return printJson(data);
  printKv(data as Record<string, unknown>);
}

async function cmdAudit(
  run: ToolRunner,
  opts: { limit?: number; tool?: string; since?: string; level?: string; json: boolean },
): Promise<void> {
  const args: Record<string, unknown> = {};
  if (opts.limit !== undefined) args.limit = opts.limit;
  if (opts.tool !== undefined) args.tool = opts.tool;
  if (opts.since !== undefined) args.since = opts.since;
  if (opts.level !== undefined) args.level = opts.level;
  const result = await run("system_get_audit_log", args);
  const items = result.data as Record<string, unknown>[];
  if (opts.json) return printJson(items);
  if (!items?.length) { outputLine("No audit entries found"); return; }
  printTable(items.map((entry) => ({
    timestamp: entry["ts"],
    level: entry["level"],
    tool: entry["tool"],
    message: entry["message"],
    elapsed_ms: entry["elapsed"],
  })));
}
